"use strict";
// Runs JavaScript from a string: a Node island from the load on.
const vm = require("node:vm");
const middle = require("middle");

exports.evaluate = (source) => vm.runInNewContext(source);
exports.makeInfo = (label) => middle.makeInfo(label);
exports.touch = (info) => middle.touch(info);
exports.leafOf = (info) => info.leaf;
